<template>
  <q-dialog :model-value="visible" @update:model-value="$emit('update:visible', $event)" persistent>
    <q-card class="test-doc-picker-card">
      <q-toolbar class="bg-primary text-white">
        <q-icon name="science" size="md" class="q-mr-sm" />
        <q-toolbar-title>
          {{ $t('select_test_document') }}
        </q-toolbar-title>
        <q-btn flat round dense icon="close" @click="$emit('update:visible', false)" />
      </q-toolbar>

      <q-card-section>
        <div class="text-body2 text-grey-7 q-mb-md">
          {{ $t('select_test_document_description') }}
        </div>

        <!-- Mode toggle -->
        <q-tabs
          v-model="mode"
          dense
          class="q-mb-md"
          active-color="primary"
          indicator-color="primary"
          align="left"
          narrow-indicator
        >
          <q-tab name="search" icon="search" :label="$t('search_document')" />
          <q-tab name="custom" icon="data_object" :label="$t('wf_custom_data')" />
        </q-tabs>

        <!-- Search mode -->
        <template v-if="mode === 'search'">
          <q-input
            v-model="searchQuery"
            outlined
            dense
            :placeholder="$t('search')"
            class="q-mb-md"
            @update:model-value="debouncedSearch"
          >
            <template v-slot:prepend>
              <q-icon name="search" />
            </template>
            <template v-slot:append>
              <q-icon v-if="searchQuery" name="close" class="cursor-pointer" @click="searchQuery = ''; documents = []" />
            </template>
          </q-input>

          <q-list bordered separator class="rounded-borders document-list">
            <q-item v-if="loading" class="justify-center q-pa-md">
              <q-spinner color="primary" size="2em" />
            </q-item>

            <q-item
              v-for="doc in documents"
              :key="doc.id"
              clickable
              v-ripple
              :active="selectedDoc?.id === doc.id"
              active-class="bg-primary text-white"
              @click="selectedDoc = doc"
            >
              <q-item-section avatar>
                <q-icon name="description" :color="selectedDoc?.id === doc.id ? 'white' : 'primary'" />
              </q-item-section>
              <q-item-section>
                <q-item-label>{{ doc.filename || doc.id }}</q-item-label>
                <q-item-label caption :class="selectedDoc?.id === doc.id ? 'text-white' : ''">
                  {{ $t(doc.status) }} &bull; {{ doc.assigned_to || '' }}
                </q-item-label>
              </q-item-section>
            </q-item>

            <q-item v-if="!loading && documents.length === 0 && searchQuery.length > 1">
              <q-item-section class="text-grey text-center">
                {{ $t('no_document_found') }}
              </q-item-section>
            </q-item>

            <q-item v-if="!loading && searchQuery.length < 2">
              <q-item-section class="text-grey text-center">
                {{ $t('wf_search_document_to_test') }}
              </q-item-section>
            </q-item>
          </q-list>
        </template>

        <!-- Custom data mode -->
        <template v-if="mode === 'custom'">
          <div class="text-caption text-grey-7 q-mb-sm">
            {{ $t('wf_custom_data_description') }}
          </div>
          <q-input
            v-model="customDataRaw"
            outlined
            type="textarea"
            :placeholder="customDataPlaceholder"
            :error="!!customDataError"
            :error-message="customDataError"
            input-style="font-family: monospace; font-size: 12px; height: 300px; overflow-y: auto; resize: none"
          />
        </template>
      </q-card-section>

      <q-card-actions align="right" class="q-pa-md">
        <q-btn
          flat
          :label="$t('test_without_document')"
          color="grey-7"
          icon="play_arrow"
          @click="emitTest(null)"
        />
        <q-btn
          v-if="mode === 'search'"
          unelevated
          :label="$t('test')"
          color="primary"
          icon="science"
          :disable="!selectedDoc"
          @click="emitTest(selectedDoc?.id)"
        />
        <q-btn
          v-if="mode === 'custom'"
          unelevated
          :label="$t('test')"
          color="primary"
          icon="science"
          :disable="!customDataRaw.trim() || !!customDataError"
          @click="emitTestCustom"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { debounce } from 'quasar';
import { documentListApiService } from 'src/services';

export interface TestDocumentPayload {
  doc_id?: string;
  doc_data?: Record<string, any>;
}

export default defineComponent({
  name: 'WorkflowTestDocumentPicker',

  props: {
    visible: {
      type: Boolean,
      required: true,
    },
  },

  emits: ['update:visible', 'test'],

  data() {
    return {
      mode: 'search' as 'search' | 'custom',
      documents: [] as any[],
      selectedDoc: null as any,
      searchQuery: '',
      loading: false,
      customDataRaw: '',
      customDataError: '',
      customDataPlaceholder: `{
  "$comment": "Full document data with layout.",
}
`,
    };
  },

  created() {
    this.debouncedSearch = debounce(() => this.searchDocuments(), 500);
  },

  watch: {
    visible(val: boolean) {
      if (val) {
        this.selectedDoc = null;
        this.searchQuery = '';
        this.documents = [];
        this.customDataRaw = '';
        this.customDataError = '';
        this.mode = 'search';
      }
    },
    mode() {
      // Clear the other mode's selection when switching
      if (this.mode === 'search') {
        this.customDataRaw = '';
        this.customDataError = '';
      } else {
        this.selectedDoc = null;
        this.searchQuery = '';
        this.documents = [];
      }
    },
    customDataRaw(val: string) {
      this.customDataError = '';
      if (!val.trim()) return;
      try {
        const parsed = JSON.parse(val);
        if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
          this.customDataError = 'Must be a JSON object';
        }
      } catch {
        this.customDataError = 'Invalid JSON';
      }
    },
  },

  methods: {
    debouncedSearch() {},

    async searchDocuments() {
      if (this.searchQuery.length < 2) {
        this.documents = [];
        return;
      }
      this.loading = true;
      try {
        const response = await documentListApiService.getList(
          `?keyword=${this.searchQuery}`,
        );
        this.documents = response?.documents || [];
      } catch (err) {
        console.error('Failed to search documents:', err);
        this.documents = [];
      } finally {
        this.loading = false;
      }
    },

    emitTest(docId: string | null) {
      const payload: TestDocumentPayload = {};
      if (docId) {
        payload.doc_id = docId;
      }
      this.$emit('test', payload);
    },

    emitTestCustom() {
      if (this.customDataError || !this.customDataRaw.trim()) return;
      try {
        const parsed = JSON.parse(this.customDataRaw);
        this.$emit('test', { doc_data: parsed } as TestDocumentPayload);
      } catch {
        this.customDataError = 'Invalid JSON';
      }
    },
  },
});
</script>

<style scoped>
.test-doc-picker-card {
  min-width: 500px;
  max-width: 650px;
}

.document-list {
  max-height: 300px;
  overflow-y: auto;
}

</style>
